        [53, 54, 55, 55, 55, 56, 56, 57, 58, 58],
        [59, 60, 61, 62, 62, 62, 62, 63, 64, 64]
    ],
    'row_water_counts': [5, 3, 3, 7, 1, 1, 5, 6, 3, 2],
    'col_water_counts': [3, 2, 2, 6, 4, 5, 4, 4, 4, 2]
}

def solve(observation):
    region_grid = observation['region']
    row_targets = observation['row_water_counts']
    col_targets = observation['col_water_counts']

    rows = len(region_grid)
    cols = len(region_grid[0])

    # Precompute region members sorted by row index for efficient vertical propagation
    # regions_map: region_id -> list of (row, col) sorted by row ascending
    regions_map = {}
    for r in range(rows):
        for c in range(cols):
            rid = region_grid[r][c]
            if rid not in regions_map:
                regions_map[rid] = []
            regions_map[rid].append((r, c))

    for rid in regions_map:
        regions_map[rid].sort(key=lambda x: x[0])

    # State constants
    UNKNOWN = -1
    EMPTY = 0
    WATER = 1

    def solve_recursive(grid):
        """
        Recursive solver with constraint propagation.
        Returns the solved grid or None if no solution.
        """

        # --- Constraint Propagation Phase ---
        changed = True
        while changed:
            changed = False

            # 1. Row Constraints
            for r in range(rows):
                current_water = 0
                unknowns = 0
                for c in range(cols):
                    if grid[r][c] == WATER: current_water += 1
                    elif grid[r][c] == UNKNOWN: unknowns += 1

                target = row_targets[r]

                # Contradiction checks
                if current_water > target: return None
                if current_water + unknowns < target: return None

                # Deductions
                if current_water == target:
                    # Remaining unknowns must be empty
                    for c in range(cols):
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = EMPTY
                            changed = True
                elif unknowns == (target - current_water):
                    # Remaining unknowns must be water
                    for c in range(cols):
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = WATER
                            changed = True

            # 2. Column Constraints
            for c in range(cols):
                current_water = 0
                unknowns = 0
                for r in range(rows):
                    if grid[r][c] == WATER: current_water += 1
                    elif grid[r][c] == UNKNOWN: unknowns += 1

                target = col_targets[c]

                if current_water > target: return None
                if current_water + unknowns < target: return None

                if current_water == target:
                    for r in range(rows):
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = EMPTY
                            changed = True
                elif unknowns == (target - current_water):
                    for r in range(rows):
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = WATER
                            changed = True

            # 3. Region Consistency (Aquarium Rule)
            # If a cell is Water, all cells in the same region BELOW it must be Water.
            # If a cell is Empty, all cells in the same region ABOVE it must be Empty.
            for r in range(rows):
                for c in range(cols):
                    cell_val = grid[r][c]
                    if cell_val != UNKNOWN:
                        rid = region_grid[r][c]
                        reg_cells = regions_map[rid]

                        if cell_val == WATER:
                            # Force water downwards
                            for (nr, nc) in reg_cells:
                                if nr > r:
                                    if grid[nr][nc] == EMPTY: return None # Conflict
                                    if grid[nr][nc] == UNKNOWN:
                                        grid[nr][nc] = WATER
                                        changed = True
                        elif cell_val == EMPTY:
                            # Force empty upwards
                            for (nr, nc) in reg_cells:
                                if nr < r:
                                    if grid[nr][nc] == WATER: return None # Conflict
                                    if grid[nr][nc] == UNKNOWN:
                                        grid[nr][nc] = EMPTY
                                        changed = True

        # --- Search Phase ---
        # Find the first unknown cell to branch on
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == UNKNOWN:
                    # Try assigning WATER
                    grid_copy_water = [row[:] for row in grid]
                    grid_copy_water[r][c] = WATER
                    result = solve_recursive(grid_copy_water)
                    if result is not None:
                        return result

                    # Try assigning EMPTY
                    grid_copy_empty = [row[:] for row in grid]
                    grid_copy_empty[r][c] = EMPTY
                    result = solve_recursive(grid_copy_empty)
                    if result is not None:
                        return result

                    # Both branches failed
                    return None

        # No unknowns left, this is a valid solution
        return grid

    # Initial grid setup
    initial_grid = [[UNKNOWN for _ in range(cols)] for _ in range(rows)]

    solution = solve_recursive(initial_grid)

    if not solution:
        return "No Solution"

    # Format output according to specifications
    output_grid = []
    for r in range(rows):
        row_output = []
        for c in range(cols):
            if solution[r][c] == WATER:
                row_output.append('W')
            else:
                row_output.append(None)
        output_grid.append(row_output)

    return output_grid

if __name__ == "__main__":
    print(solve(OBSERVATION))

