    'col_water_counts': [1, 4, 3, 2, 2, 2, 5, 5, 8, 3]
}

def solve(observation):
    """
    Solves the Aquarium/Water puzzle using constraint propagation and backtracking.
    Rules:
    1. Each region fills from bottom with consistent water level.
    2. Row/Col sums match clues.
    """
    region_grid = observation['region']
    row_targets = observation['row_water_counts']
    col_targets = observation['col_water_counts']

    R = len(region_grid)
    C = len(region_grid[0]) if R > 0 else 0

    # Build region lookup: ID -> list of (row, col) sorted bottom-to-top
    regions = {}
    for r in range(R):
        for c in range(C):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    # Sort each region's cells: primary key row descending (bottom up), secondary col ascending
    for rid in regions:
        regions[rid].sort(key=lambda x: (-x[0], x[1]))

    # Grid state: None = unknown, 'W' = water, '.' = dry (empty)
    grid = [[None for _ in range(C)] for _ in range(R)]

    # Precompute reverse mappings for fast access
    cell_to_region = [[None]*C for _ in range(R)]
    for rid, cells in regions.items():
        for r, c in cells:
            cell_to_region[r][c] = rid

    def get_row_state(r):
        """Returns (water_count, dry_count, unknown_count) for row r"""
        w = d = 0
        for c in range(C):
            v = grid[r][c]
            if v == 'W': w += 1
            elif v == '.': d += 1
        return w, d, C - w - d

    def get_col_state(c):
        """Returns (water_count, dry_count, unknown_count) for col c"""
        w = d = 0
        for r in range(R):
            v = grid[r][c]
            if v == 'W': w += 1
            elif v == '.': d += 1
        return w, d, R - w - d

    def propagate():
        """
        Applies constraint propagation rules until no changes or contradiction found.
        Returns False if contradiction detected, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # Rule 1: Row constraints
            for r in range(R):
                w, d, u = get_row_state(r)
                target = row_targets[r]

                if w > target: return False  # Overflow
                if w + u < target: return False  # Underflow impossible

                # If row is complete (w == target), mark all unknowns as dry
                if w == target and u > 0:
                    for c in range(C):
                        if grid[r][c] is None:
                            grid[r][c] = '.'
                            changed = True

                # If remaining unknowns exactly match needed water, force them
                if u > 0 and w + u == target:
                    for c in range(C):
                        if grid[r][c] is None:
                            grid[r][c] = 'W'
                            changed = True

            # Rule 2: Column constraints
            for c in range(C):
                w, d, u = get_col_state(c)
                target = col_targets[c]

                if w > target: return False
                if w + u < target: return False

                if w == target and u > 0:
                    for r in range(R):
                        if grid[r][c] is None:
                            grid[r][c] = '.'
                            changed = True

                if u > 0 and w + u == target:
                    for r in range(R):
                        if grid[r][c] is None:
                            grid[r][c] = 'W'
                            changed = True

            # Rule 3: Region consistency (gravity rule)
            # In a region, if a cell is 'W', all cells below it (higher row index) must be 'W'.
            # If a cell is '.', all cells above it (lower row index) must be '.'.
            for rid, cells in regions.items():
                # Check sorted bottom-to-top
                seen_dry = False
                for r, c in cells:
                    val = grid[r][c]
                    if val == 'W' and seen_dry:
                        return False  # Water above dry in same region
                    if val == '.':
                        seen_dry = True

                # Propagate: if bottom-most known is W, everything below it (already checked) is W,
                # but we can infer that if any cell is W, all lower-indexed cells in sorted list must be W
                # If top-most known is '.', all higher-indexed must be '.'

                # Find boundary between known W and known .
                # Scan from bottom (index 0) upwards
                last_w_idx = -1
                first_dot_idx = len(cells)

                for i, (r, c) in enumerate(cells):
                    if grid[r][c] == 'W':
                        last_w_idx = i
                    elif grid[r][c] == '.':
                        if first_dot_idx == len(cells):
                            first_dot_idx = i

                # Force water between last_w and first_dot if gap exists
                # Actually simpler: if we see W at index i, indices 0..i must be W
                # If we see . at index j, indices j..end must be .
                for i, (r, c) in enumerate(cells):
                    if grid[r][c] is None:
                        if i <= last_w_idx:  # Below a water cell
                            grid[r][c] = 'W'
                            changed = True
                        elif i >= first_dot_idx:  # Above a dry cell
                            grid[r][c] = '.'
                            changed = True

        return True

    def is_complete():
        """Check if grid fully satisfies all constraints"""
        for r in range(R):
            w, _, _ = get_row_state(r)
            if w != row_targets[r]: return False
        for c in range(C):
            w, _, _ = get_col_state(c)
            if w != col_targets[c]: return False
        for r in range(R):
            for c in range(C):
                if grid[r][c] is None: return False
        return True

    # Ordering regions for backtracking: Most Constrained Variable (MCV) heuristic
    # Prefer smaller domains (shorter regions) or regions touching constrained rows/cols
    # Here we sort by size ascending (smaller regions have fewer level options)
    region_order = sorted(regions.keys(), key=lambda rid: len(regions[rid]))

    def backtrack(idx):
        if idx == len(region_order):
            return is_complete()

        rid = region_order[idx]
        cells = regions[rid]
        n_cells = len(cells)

        # Save state for restoration
        saved_state = [(r, c, grid[r][c]) for r, c in cells if grid[r][c] is not None]

        # Calculate feasible level range based on current assignments
        # Min level: count of cells already forced W
        min_level = sum(1 for r, c in cells if grid[r][c] == 'W')

        # Max level: n_cells minus cells forced dry, but also limited by row/col capacities
        # Quick upper bound
        max_level = n_cells - sum(1 for r, c in cells if grid[r][c] == '.')

        # Try each possible level from min to max
        for level in range(min_level, max_level + 1):
            # Apply hypothesis: bottom 'level' cells are W, rest are .
            valid = True
            for i, (r, c) in enumerate(cells):
                if i < level:
                    if grid[r][c] == '.':  # Conflict
                        valid = False
                        break
                    if grid[r][c] is None:
                        grid[r][c] = 'W'
                else:
                    if grid[r][c] == 'W':  # Conflict
                        valid = False
                        break
                    if grid[r][c] is None:
                        grid[r][c] = '.'

            if not valid:
                # Undo changes made in this iteration
                for i, (r, c) in enumerate(cells):
                    if i < level and (r, c, 'W') not in [(sr, sc, sv) for sr, sc, sv in saved_state if sv=='W']:
                        if grid[r][c] == 'W' and (r,c) not in [x[0:2] for x in saved_state]:
                            grid[r][c] = None
                    elif i >= level and (r, c, '.') not in [(sr, sc, sv) for sr, sc, sv in saved_state if sv=='.']:
                        if grid[r][c] == '.' and (r,c) not in [x[0:2] for x in saved_state]:
                            grid[r][c] = None
                continue

            # Propagate constraints
            if propagate():
                if backtrack(idx + 1):
                    return True

            # Restore state for this region's cells
            for r, c, val in saved_state:
                grid[r][c] = val
            for r, c in cells:
                if (r, c) not in [(x[0], x[1]) for x in saved_state]:
                    grid[r][c] = None

        return False

    # Initial propagation before search
    if not propagate():
        return "No Solution"

    if backtrack(0):
        # Format output: 'W' for water, None for non-water
        result = []
        for r in range(R):
            row_result = []
            for c in range(C):
                if grid[r][c] == 'W':
                    row_result.append('W')
                else:
                    row_result.append(None)
            result.append(row_result)
        return result

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

