                            if len(doms[nr][c]) > 1:
                                doms[nr][c] = {opp}
                                changed = True

            # --- Rule 2: No Three Consecutive Identical Colors ---
            # Horizontal triplets
            for r in range(n_rows):
                for c in range(n_cols - 2):
                    d1, d2, d3 = doms[r][c], doms[r][c+1], doms[r][c+2]

                    # Pattern: XX_ => last must be opposite
                    if len(d1) == 1 and len(d2) == 1:
                        v = next(iter(d1))
                        if v == next(iter(d2)):
                            if v in d3:
                                new_d3 = d3 - {v}
                                if not new_d3: return False
                                if len(new_d3) < len(d3):
                                    doms[r][c+2] = new_d3
                                    changed = True

                    # Pattern: _XX => first must be opposite
                    if len(d2) == 1 and len(d3) == 1:
                        v = next(iter(d2))
                        if v == next(iter(d3)):
                            if v in d1:
                                new_d1 = d1 - {v}
                                if not new_d1: return False
                                if len(new_d1) < len(d1):
                                    doms[r][c] = new_d1
                                    changed = True

