            for r in range(n_rows - 2):
                for c in range(n_cols):
                    d1, d2, d3 = doms[r][c], doms[r+1][c], doms[r+2][c]

                    if len(d1) == 1 and len(d2) == 1:
                        v = next(iter(d1))
                        if v == next(iter(d2)):
                            if v in d3:
                                new_d3 = d3 - {v}
                                if not new_d3: return False
                                if len(new_d3) < len(d3):
                                    doms[r+2][c] = new_d3
                                    changed = True

                    if len(d2) == 1 and len(d3) == 1:
                        v = next(iter(d2))
                        if v == next(iter(d3)):
                            if v in d1:
                                new_d1 = d1 - {v}
                                if not new_d1: return False
                                if len(new_d1) < len(d1):
                                    doms[r][c] = new_d1
                                    changed = True

            # --- Rule 3: Row/Column Balance (Count Constraints) ---
            target = n_rows // 2  # Assuming square grid for equal counts

            # Row checks
            for r in range(n_rows):
                b_cnt = sum(1 for c in range(n_cols) if doms[r][c] == {'B'})
                w_cnt = sum(1 for c in range(n_cols) if doms[r][c] == {'W'})

                if b_cnt > target or w_cnt > target:
                    return False

                if b_cnt == target:
                    # Fill remaining with W
                    for c in range(n_cols):
                        if len(doms[r][c]) > 1:
                            if 'B' in doms[r][c]:
                                doms[r][c] = doms[r][c] - {'B'}
                                if not doms[r][c]: return False
                                changed = True
                if w_cnt == target:
                    # Fill remaining with B
                    for c in range(n_cols):
                        if len(doms[r][c]) > 1:
                            if 'W' in doms[r][c]:
                                doms[r][c] = doms[r][c] - {'W'}
                                if not doms[r][c]: return False
                                changed = True

            # Column checks
            for c in range(n_cols):
                b_cnt = sum(1 for r in range(n_rows) if doms[r][c] == {'B'})
                w_cnt = sum(1 for r in range(n_rows) if doms[r][c] == {'W'})

                if b_cnt > target or w_cnt > target:
                    return False

                if b_cnt == target:
                    for r in range(n_rows):
                        if len(doms[r][c]) > 1:
                            if 'B' in doms[r][c]:
                                doms[r][c] = doms[r][c] - {'B'}
                                if not doms[r][c]: return False
                                changed = True
                if w_cnt == target:
                    for r in range(n_rows):
                        if len(doms[r][c]) > 1:
                            if 'W' in doms[r][c]:
                                doms[r][c] = doms[r][c] - {'W'}
                                if not doms[r][c]: return False
                                changed = True

        return True

    def search(doms):
        """
        Recursive backtracking search with constraint propagation.
        Uses MRV (Minimum Remaining Values) heuristic for variable selection.
        """
        # Propagate constraints first
        if not propagate(doms):
            return None

        # Find the unfilled cell with minimum remaining values (MRV)
        min_options = 3
        best_cell = None

        for r in range(n_rows):
            for c in range(n_cols):
                opts = len(doms[r][c])
                if opts == 0:
                    return None  # Dead end
                if opts > 1 and opts < min_options:
                    min_options = opts
                    best_cell = (r, c)

        # If no unfilled cells found, we have a solution
        if best_cell is None:
            return [[next(iter(doms[r][c])) for c in range(n_cols)] for r in range(n_rows)]

        r, c = best_cell
        # Try each possible value for the chosen cell
        for val in list(doms[r][c]):
            # Create a deep enough copy for recursion (shallow copy of rows, but we replace sets entirely)
            new_domains = [row[:] for row in doms]
            new_domains[r][c] = {val}

            result = search(new_domains)
            if result is not None:
                return result

        return None  # No valid assignment found

    solution = search(domains)
    return solution if solution else "No Solution"

