import ast

def solve(observation):
    # Parse initial state
    data = observation['data']
    raw_h = observation['horizontal']
    raw_v = observation['vertical']

    N = len(data)
    TARGET = N // 2

    # Deep copy grid to avoid mutating original observation
    grid = [[data[r][c] for c in range(N)] for r in range(N)]

    # Parse constraints into coordinate-based dictionaries
    # h_constr[(r, c)] represents constraint between (r, c) and (r, c+1)
    h_constr = {}
    for k, v in raw_h.items():
        r, c = ast.literal_eval(k)
        h_constr[(int(r), int(c))] = v

    v_constr = {}
    for k, v in raw_v.items():
        r, c = ast.literal_eval(k)
        v_constr[(int(r), int(c))] = v

    def opposite(color):
        return 'W' if color == 'B' else 'B'

    def get_counts():
        row_b = [0]*N
        row_w = [0]*N
        col_b = [0]*N
        col_w = [0]*N
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 'B':
                    row_b[r] += 1
                    col_b[c] += 1
                elif grid[r][c] == 'W':
                    row_w[r] += 1
                    col_w[c] += 1
        return row_b, row_w, col_b, col_w

    def propagate():
        """
        Applies logical deduction rules until no further progress can be made.
        Returns False if a contradiction is detected, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # --- Rule 1 & 4: Adjacency Constraints (= and x) ---
            # Process horizontal constraints
            for (r, c), rel in h_constr.items():
                v1, v2 = grid[r][c], grid[r][c+1]
                if v1 and v2:
                    if (rel == '=' and v1 != v2) or (rel == 'x' and v1 == v2):
                        return False # Contradiction
                elif v1 and not v2:
                    grid[r][c+1] = v1 if rel == '=' else opposite(v1)
                    changed = True
                elif v2 and not v1:
                    grid[r][c] = v2 if rel == '=' else opposite(v2)
                    changed = True

            # Process vertical constraints
            for (r, c), rel in v_constr.items():
                v1, v2 = grid[r][c], grid[r+1][c]
                if v1 and v2:
                    if (rel == '=' and v1 != v2) or (rel == 'x' and v1 == v2):
                        return False
                elif v1 and not v2:
                    grid[r+1][c] = v1 if rel == '=' else opposite(v1)
                    changed = True
                elif v2 and not v1:
                    grid[r][c] = v2 if rel == '=' else opposite(v2)
                    changed = True

            # --- Rule 2: No Three Consecutive ---
            # Check Rows
            for r in range(N):
                for c in range(N-2):
                    v1, v2, v3 = grid[r][c], grid[r][c+1], grid[r][c+2]
                    if v1 and v2 and v3:
                        if v1 == v2 == v3: return False
                    elif v1 and v2 and v1 == v2:
                        if not v3: grid[r][c+2] = opposite(v1); changed = True
                    elif v2 and v3 and v2 == v3:
                        if not v1: grid[r][c] = opposite(v2); changed = True
                    elif v1 and v3 and v1 == v3:
                        if not v2: grid[r][c+1] = opposite(v1); changed = True

            # Check Columns
            for c in range(N):
                for r in range(N-2):
                    v1, v2, v3 = grid[r][c], grid[r+1][c], grid[r+2][c]
                    if v1 and v2 and v3:
                        if v1 == v2 == v3: return False
                    elif v1 and v2 and v1 == v2:
                        if not v3: grid[r+2][c] = opposite(v1); changed = True
                    elif v2 and v3 and v2 == v3:
                        if not v1: grid[r][c] = opposite(v2); changed = True
                    elif v1 and v3 and v1 == v3:
                        if not v2: grid[r+1][c] = opposite(v1); changed = True

            # --- Rule 1 & 3: Count Constraints (Equal B/W, Max Limits) ---
            rb, rw, cb, cw = get_counts()

            for r in range(N):
                # If max reached, fill rest with opposite
                if rb[r] == TARGET:
                    for c in range(N):
                        if not grid[r][c]: grid[r][c] = 'W'; changed = True
                if rw[r] == TARGET:
                    for c in range(N):
