                            elif v_con[r-1][c] == 'x':
                                if neigh is not None and neigh == current: return False
                                if neigh is None:
                                    grid[r-1][c] = opp; changed = True

            # Global/Rules-based deductions
            for i in range(N):
                # Count existing
                row_counts = {'B': 0, 'W': 0}
                col_counts = {'B': 0, 'W': 0}
                row_none_idx = []
                col_none_idx = []

                for j in range(N):
                    rv = grid[i][j]
                    cv = grid[j][i]
                    if rv: row_counts[rv] += 1
                    else: row_none_idx.append(j)
                    if cv: col_counts[cv] += 1
                    else: col_none_idx.append(j)

