                    if v1 and v3 and v1==v3:
                        if v2 is None: grid[i][j+1] = ('W' if v1=='B' else 'B'); changed=True
                        elif v2!=v1: pass # ok
                        elif v2==v1: return False # shouldn't happen if logic holds but safety check

                # Col scan
                for j in range(N-2):
                    v1, v2, v3 = grid[j][i], grid[j+1][i], grid[j+2][i]
                    if v1 and v2 and v1==v2:
                        if v3 is None: grid[j+2][i] = ('W' if v1=='B' else 'B'); changed=True
                        elif v3==v1: return False
                    if v2 and v3 and v2==v3:
                        if v1 is None: grid[j][i] = ('W' if v2=='B' else 'B'); changed=True
                        elif v1==v2: return False
                    if v1 and v3 and v1==v3:
                        if v2 is None: grid[j+1][i] = ('W' if v1=='B' else 'B'); changed=True

        return True

    def is_complete():
        return all(grid[r][c] is not None for r in range(N) for c in range(N))

    def solve_step():
        # 1. Propagate
        if not propagate():
            return None # Contradiction

        if is_complete():
            return grid

        # 2. Find best candidate for branching (MRV heuristic)
        # Pick cell with minimum remaining values (ideally 2, but constrained)
        best_cell = None
        min_possibilities = 3

        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    poss = 0
                    for color in ['B', 'W']:
                        # Create hypothetical state
                        saved = grid[r][c]
                        grid[r][c] = color
                        # Quick validity check locally
                        valid = True
                        # Check immediate neighbors for triple
                        if valid:
                            if (c>=2 and grid[r][c-1]==color and grid[r][c-2]==color): valid=False
                            if (c<=N-3 and grid[r][c+1]==color and grid[r][c+2]==color): valid=False
                            if (r>=2 and grid[r-1][c]==color and grid[r-2][c]==color): valid=False
                            if (r<=N-3 and grid[r+1][c]==color and grid[r+2][c]==color): valid=False
                        # Check counts
                        if valid:
                            cnt_r = sum(1 for x in grid[r] if x == color)
                            cnt_c = sum(1 for k in range(N) if grid[k][c] == color)
                            if cnt_r > TARGET_COUNT or cnt_c > TARGET_COUNT: valid=False

                        if valid: poss += 1
                        grid[r][c] = saved # Restore

                    if poss == 0: return None # Dead end
                    if poss < min_possibilities:
                        min_possibilities = poss
                        best_cell = (r, c)

        if best_cell is None:
            return None # Should be caught by is_complete, but safety

        r, c = best_cell
        for color in ['B', 'W']:
            # Save state
            snapshot = [row[:] for row in grid]
            grid[r][c] = color

            result = solve_step()
            if result is not None:
                return result

            # Restore state
            for i in range(N):
                grid[i] = snapshot[i]

        return None

    result_grid = solve_step()
    if result_grid:
        return result_grid
    return "No Solution"

