            if initial_data[r][c] is not None:
                domains[r][c] = {initial_data[r][c]}

    # Parse inequality constraints into a unified list of (r1, c1, r2, c2) 
    # representing: value at (r1, c1) < value at (r2, c2)
    constraints = []

    # Process horizontal inequalities: stored at (row, col+0.5)
    for key, symbol in observation['horizontal'].items():
        # Parse coordinate string like "(0, 1.5)"
        try:
            r_str, c_str = key.strip('()').split(', ')
            r = int(r_str)
            c_float = float(c_str)
        except:
            continue

        left_c = int(c_float - 0.5)
        right_c = int(c_float + 0.5)

        if symbol == '<':
            constraints.append((r, left_c, r, right_c))
        elif symbol == '>':
            constraints.append((r, right_c, r, left_c))

    # Process vertical inequalities: stored at (row+0.5, col)
    for key, symbol in observation['vertical'].items():
        # Parse coordinate string like "(1.5, 1)"
        try:
            r_str, c_str = key.strip('()').split(', ')
            r_float = float(r_str)
            c = int(c_str)
        except:
            continue

        top_r = int(r_float - 0.5)
        bot_r = int(r_float + 0.5)

        if symbol == '^':  # Top is less than bottom
            constraints.append((top_r, c, bot_r, c))
        elif symbol == 'v': # Bottom is less than top (Top is greater than bottom)
            constraints.append((bot_r, c, top_r, c))

    def propagate(current_domains):
        """
        Applies constraint propagation to reduce domains.
        Returns False if a contradiction is detected (any domain becomes empty).
        """
        changed = True
        while changed:
            changed = False

            # 1. Peer Elimination (Naked Singles propagation)
            # If a cell has only one possible value, remove it from all peers in same row/col
            for r in range(N):
                for c in range(N):
                    if len(current_domains[r][c]) == 1:
                        val = next(iter(current_domains[r][c]))

                        # Check row peers
                        for cc in range(N):
                            if cc != c and val in current_domains[r][cc]:
                                current_domains[r][cc].discard(val)
                                changed = True
                                if not current_domains[r][cc]:
