                                current_domains[rr][c].discard(val)
                                changed = True
                                if not current_domains[rr][c]:
                                    return False

            # 2. Inequality Constraint Pruning
            # For constraint (A < B): 
            #   - Max possible value of A limits minimum of B
            #   - Min possible value of B limits maximum of A
            for r1, c1, r2, c2 in constraints:
                d1 = current_domains[r1][c1]
                d2 = current_domains[r2][c2]

                if d1 and d2:
                    # Prune d2 based on max of d1
                    max_d1 = max(d1)
                    invalid_d2 = {x for x in d2 if x <= max_d1}
                    if invalid_d2:
                        d2 -= invalid_d2
                        changed = True
                        if not d2:
                            return False

                    # Prune d1 based on min of d2
                    min_d2 = min(d2)
                    invalid_d1 = {x for x in d1 if x >= min_d2}
                    if invalid_d1:
                        d1 -= invalid_d1
                        changed = True
                        if not d1:
                            return False
        return True

    def backtrack(current_domains):
        """
        Recursive backtracking search with MRV heuristic.
        """
        # Run propagation first to reduce search space and check for immediate failures
        if not propagate(current_domains):
            return None

        # Find the unassigned cell with the fewest remaining possibilities (MRV Heuristic)
        min_remaining = N + 1
        best_cell = None

        for r in range(N):
            for c in range(N):
                domain_size = len(current_domains[r][c])
                if domain_size == 0:
                    return None  # Contradiction found
                if domain_size > 1 and domain_size < min_remaining:
                    min_remaining = domain_size
                    best_cell = (r, c)

        # If no unassigned cells with size > 1 are found, puzzle is solved
        if best_cell is None:
            # Verify all cells are singleton (solved)
            solution = []
            for r in range(N):
                row = []
                for c in range(N):
                    if len(current_domains[r][c]) != 1:
                        return None # Should not happen if logic is correct
                    row.append(next(iter(current_domains[r][c])))
                solution.append(row)
            return solution

        r, c = best_cell

        # Try each value in the domain of the selected cell
        for val in list(current_domains[r][c]):
            # Create a deep copy of the domains for this branch
            new_domains = deepcopy(current_domains)
            new_domains[r][c] = {val}  # Assign the value

            result = backtrack(new_domains)
            if result is not None:
                return result

        return None  # No valid value led to a solution, trigger backtrack

    # Execute the solver
    final_solution = backtrack(domains)
    return final_solution if final_solution else "No Solution"

