        '(3, 0.5)': '<'
    },
    'vertical': {
        '(2.5, 3)': 'v',
        '(3.5, 4)': 'v'
    }
}

def solve(observation):
    """
    Solves the Futoshiki (Inequality Grid) puzzle using constraint propagation 
    and backtracking search with the Minimum Remaining Values (MRV) heuristic.
    """
    data = observation['data']
    h_constraints = observation['horizontal']
    v_constraints = observation['vertical']

    N = len(data)
    # Deep copy the initial board state to avoid mutating the original observation
    board = [row[:] for row in data]

    def get_candidates(r, c):
        """
        Returns the set of valid numbers for cell (r, c) based on current 
        board state, Latin Square rules, and inequality constraints.
        """
        if board[r][c] is not None:
            return set()

        # Start with all possible values
        candidates = set(range(1, N + 1))

        # 1. Eliminate based on row and column uniqueness (Latin Square)
        for i in range(N):
            if board[r][i] is not None:
                candidates.discard(board[r][i])
            if board[i][c] is not None:
                candidates.discard(board[i][c])

        # 2. Eliminate based on horizontal inequalities
        # Check neighbor to the left
        left_key = f"({r}, {c - 0.5})"
        if left_key in h_constraints:
            neighbor_val = board[r][c - 1]
            symbol = h_constraints[left_key]
            if neighbor_val is not None:
                if symbol == '>':  # Left > Current
                    candidates = {x for x in candidates if x < neighbor_val}
                elif symbol == '<':  # Left < Current
                    candidates = {x for x in candidates if x > neighbor_val}

        # Check neighbor to the right
        right_key = f"({r}, {c + 0.5})"
        if right_key in h_constraints:
            neighbor_val = board[r][c + 1]
            symbol = h_constraints[right_key]
            if neighbor_val is not None:
                if symbol == '>':  # Current > Right
                    candidates = {x for x in candidates if x > neighbor_val}
                elif symbol == '<':  # Current < Right
                    candidates = {x for x in candidates if x < neighbor_val}

        # 3. Eliminate based on vertical inequalities
        # Check neighbor above
        top_key = f"({r - 0.5}, {c})"
        if top_key in v_constraints:
            neighbor_val = board[r - 1][c]
            symbol = v_constraints[top_key]
            if neighbor_val is not None:
                if symbol == 'v':  # Top > Current (Down arrow implies Top is greater)
                    candidates = {x for x in candidates if x < neighbor_val}
                elif symbol == '^':  # Top < Current (Up arrow implies Top is smaller)
                    candidates = {x for x in candidates if x > neighbor_val}

        # Check neighbor below
        bot_key = f"({r + 0.5}, {c})"
        if bot_key in v_constraints:
            neighbor_val = board[r + 1][c]
            symbol = v_constraints[bot_key]
            if neighbor_val is not None:
                if symbol == 'v':  # Current > Bottom
                    candidates = {x for x in candidates if x > neighbor_val}
                elif symbol == '^':  # Current < Bottom
                    candidates = {x for x in candidates if x < neighbor_val}

        return candidates

    def is_valid_placement(r, c, val):
        """
        Validates placing 'val' at (r, c) against immediate neighbors 
        satisfying inequality constraints.
        """
        # Check horizontal neighbors
        left_key = f"({r}, {c - 0.5})"
        if left_key in h_constraints and board[r][c - 1] is not None:
            if h_constraints[left_key] == '>' and not (board[r][c - 1] > val): return False
            if h_constraints[left_key] == '<' and not (board[r][c - 1] < val): return False

        right_key = f"({r}, {c + 0.5})"
        if right_key in h_constraints and board[r][c + 1] is not None:
            if h_constraints[right_key] == '>' and not (val > board[r][c + 1]): return False
            if h_constraints[right_key] == '<' and not (val < board[r][c + 1]): return False

        # Check vertical neighbors
        top_key = f"({r - 0.5}, {c})"
        if top_key in v_constraints and board[r - 1][c] is not None:
            if v_constraints[top_key] == 'v' and not (board[r - 1][c] > val): return False
            if v_constraints[top_key] == '^' and not (board[r - 1][c] < val): return False

        bot_key = f"({r + 0.5}, {c})"
        if bot_key in v_constraints and board[r + 1][c] is not None:
            if v_constraints[bot_key] == 'v' and not (val > board[r + 1][c]): return False
            if v_constraints[bot_key] == '^' and not (val < board[r + 1][c]): return False

        return True

    def backtrack():
        """
        Recursive backtracking function using MRV (Minimum Remaining Values) 
        heuristic to select the next cell to fill.
        """
        # Find the empty cell with the fewest valid candidates (MRV Heuristic)
        min_candidates_size = N + 1
        best_cell = None
        best_candidates = None

        for r in range(N):
            for c in range(N):
                if board[r][c] is None:
                    cands = get_candidates(r, c)
                    # Pruning: If any cell has zero valid candidates, fail immediately
                    if len(cands) == 0:
                        return False
                    if len(cands) < min_candidates_size:
                        min_candidates_size = len(cands)
                        best_cell = (r, c)
                        best_candidates = cands

        # If no empty cells are found, the puzzle is solved
        if best_cell is None:
            return True

        r, c = best_cell
        # Try each candidate value
        for val in best_candidates:
            if is_valid_placement(r, c, val):
                board[r][c] = val
                if backtrack():
                    return True
                # Undo assignment (backtrack)
                board[r][c] = None

        return False

    # Execute the solving process
    if backtrack():
        return board
    else:
        return "No Solution"

