def solve(observation):
    """
    Solves a Futoshiki (inequality Sudoku) puzzle using constraint propagation 
    and backtracking search with MRV (Minimum Remaining Values) heuristic.
    """

    data = observation['data']
    n = len(data)
    horiz = observation['horizontal']
    vert = observation['vertical']

    # Parse inequalities into structured format: list of (r1, c1, r2, c2) where val(r1,c1) > val(r2,c2)
    inequalities = []

    for key, symbol in horiz.items():
        # Key format: "(row, col+0.5)"
        try:
            r = int(float(key.split(',')[0].strip().replace('(', '')))
            c = float(key.split(',')[1].strip().replace(')', '')) - 0.5
            r, c = int(r), int(c)
            if symbol == '>':
                inequalities.append((r, c, r, c+1))  # left > right
            else:  # '<'
                inequalities.append((r, c+1, r, c))  # right > left
        except:
            continue

    for key, symbol in vert.items():
        # Key format: "(row+0.5, col)"
        try:
            r = float(key.split(',')[0].strip().replace('(', '')) - 0.5
            c = int(float(key.split(',')[1].strip().replace(')', '')))
            r, c = int(r), int(c)
            if symbol == 'v':
                inequalities.append((r, c, r+1, c))  # top > bottom
            else:  # '^'
                inequalities.append((r+1, c, r, c))  # bottom > top
        except:
            continue

    # Initialize candidates: for each cell, a set of possible values 1..n
    candidates = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]

    # Apply givens
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                val = data[r][c]
                candidates[r][c] = {val}

    def get_peers(r, c):
        """Returns all cells in same row or column."""
        peers = set()
        for i in range(n):
            if i != c: peers.add((r, i))
            if i != r: peers.add((i, c))
        return peers

    def propagate(cands):
        """
        Applies constraint propagation until no more changes or contradiction found.
        Returns False if contradiction detected, True otherwise.
        Modifies cands in place (should work on copy).
        """
        changed = True
        while changed:
            changed = False

            # 1. Naked Singles: If cell has 1 candidate, remove from peers
            for r in range(n):
                for c in range(n):
                    if len(cands[r][c]) == 0:
                        return False  # Contradiction
                    if len(cands[r][c]) == 1:
                        val = next(iter(cands[r][c]))
                        for pr, pc in get_peers(r, c):
                            if val in cands[pr][pc]:
                                cands[pr][pc].discard(val)
                                changed = True
                                if len(cands[pr][pc]) == 0:
                                    return False

            # 2. Hidden Singles: If value can only be in one place in row/col, assign it
            for r in range(n):
                for val in range(1, n+1):
                    places = [c for c in range(n) if val in cands[r][c]]
                    if len(places) == 0:
                        return False
                    if len(places) == 1:
                        c = places[0]
                        if len(cands[r][c]) > 1:
                            cands[r][c] = {val}
                            changed = True

            for c in range(n):
                for val in range(1, n+1):
                    places = [r for r in range(n) if val in cands[r][c]]
                    if len(places) == 0:
                        return False
                    if len(places) == 1:
                        r = places[0]
                        if len(cands[r][c]) > 1:
                            cands[r][c] = {val}
                            changed = True

            # 3. Inequality Arc Consistency
            for (r1, c1, r2, c2) in inequalities:
                # Constraint: val(r1,c1) > val(r2,c2)
                # So min of (r1,c1) must be > some value in (r2,c2)
                # And max of (r2,c2) must be < some value in (r1,c1)

                if not cands[r1][c1] or not cands[r2][c2]:
                    return False

                # Prune r1,c1: remove values that are <= all values in r2,c2 (i.e., <= min(r2,c2))
                min_right = min(cands[r2][c2])
                to_remove_left = {v for v in cands[r1][c1] if v <= min_right}
                if to_remove_left:
                    cands[r1][c1] -= to_remove_left
                    changed = True
                    if not cands[r1][c1]:
                        return False

                # Prune r2,c2: remove values that are >= all values in r1,c1 (i.e., >= max(r1,c1))
                max_left = max(cands[r1][c1])
                to_remove_right = {v for v in cands[r2][c2] if v >= max_left}
                if to_remove_right:
                    cands[r2][c2] -= to_remove_right
                    changed = True
                    if not cands[r2][c2]:
                        return False

        return True

    def solve_search(cands):
        """
        Recursive backtracking search with MRV heuristic.
        """
        # Deep copy to avoid modifying parent state incorrectly during propagation
        # Note: In Python, we need deep copies for the nested structure
        curr = [[s.copy() for s in row] for row in cands]

        if not propagate(curr):
            return None

        # Check if solved (all cells have exactly 1 candidate)
        min_len = n + 1
        best_cell = None
        for r in range(n):
            for c in range(n):
                l = len(curr[r][c])
                if l == 0:
                    return None
                if l > 1 and l < min_len:
                    min_len = l
                    best_cell = (r, c)

        if best_cell is None:
            # Solved! Extract solution
            return [[next(iter(curr[r][c])) for c in range(n)] for r in range(n)]

        r, c = best_cell
        for val in sorted(curr[r][c]):  # Try values in order
            new_cands = [[s.copy() for s in row] for row in curr]
            new_cands[r][c] = {val}
            result = solve_search(new_cands)
            if result is not None:
