                if popcount(curr_mask) == 1:
                    for pr, pc in peers[r][c]:
                        if doms[pr][pc] & curr_mask:
                            doms[pr][pc] &= ~curr_mask
                            if doms[pr][pc] == 0:
                                return False
                            if popcount(doms[pr][pc]) == 1:
                                queue.append((pr, pc))

                    for (r1, c1, r2, c2, is_lt) in inequalities:
                        if (r1, c1) != (r, c) and (r2, c2) != (r, c):
                            continue
                        d1, d2 = doms[r1][c1], doms[r2][c2]
                        nd1, nd2 = d1, d2
                        if is_lt:
                            if d2:
                                m = lowest_val(d2); nd1 &= (1 << (m-1)) - 1 if m > 1 else 0
                            if d1:
                                m = highest_val(d1); nd2 &= ALL_MASK & ~((1 << m) - 1)
                        else:
                            if d1:
                                m = lowest_val(d1); nd2 &= (1 << (m-1)) - 1 if m > 1 else 0
                            if d2:
                                m = highest_val(d2); nd1 &= ALL_MASK & ~((1 << m) - 1)
                        if nd1 != d1:
                            if nd1 == 0: return False
