        # Find unassigned cell with Minimum Remaining Values (MRV)
        min_count = N + 1
        best_cell = None

        for r in range(N):
            for c in range(N):
                cnt = popcount(doms[r][c])
                if cnt == 0:
                    return None  # Dead end
                if cnt > 1 and cnt < min_count:
                    min_count = cnt
                    best_cell = (r, c)

        # If no unassigned cells found, puzzle is solved
        if best_cell is None:
            # Convert bitmasks back to integers
            return [[popcount(doms[r][c]) == 1 and (doms[r][c].bit_length()) or 0 
                     for c in range(N)] for r in range(N)]

        r, c = best_cell

        # Try each candidate value
        for val in get_candidates(doms[r][c]):
            # Create a deep copy of domains for this branch
            new_domains = [row[:] for row in doms]

            # Assign value
            new_domains[r][c] = 1 << (val - 1)

            # Propagate constraints
            if propagate(new_domains):
                result = backtrack(new_domains)
                if result is not None:
                    return result

        return None  # All candidates failed

    # Initial propagation on the starting state
    if not propagate(domains):
        return "No Solution"

    # Start search
    solution = backtrack(domains)

    if solution:
        return solution
    else:
        return "No Solution"

