                        break
                if not block: connected = True

            if connected:
                key = frozenset({(r1, c1), (r2, c2)})
                adj[key] = 0 # Initial 0 bridges
                # Normalize order for output: top-to-bottom, left-to-right logic or just tuple sorting
                p1 = (r1, c1)
                p2 = (r2, c2)
                if p1 > p2: p1, p2 = p2, p1
                edge_geo[key] = (p1, p2)

    # State variables
    # remaining: dict {(r,c): int}
    remaining = {k:v for k,v in islands.items()}
    # bridges: dict {key: int}
    bridges = {k:0 for k in adj}

