    # s1: (p1, p2), s2: (p3, p4)
    def is_crossing(s1, s2):
        (r1, c1), (r2, c2) = s1
        (r3, c3), (r4, c4) = s2

        # One horizontal, one vertical?
        if r1 == r2 and c3 == c4:
