            # V: x=c3, y in [r3, r4]
            # Cross if c3 is strictly between c1,c2 AND r1 is strictly between r3,r4
            if (min(c1, c2) < c3 < max(c1, c2)) and (min(r3, r4) < r1 < max(r3, r4)):
