    dirs = [(0,1),(1,0),(0,-1),(-1,0)]

    def in_bounds(r, c):
        return 0 <= r < n and 0 <= c < n

    def get_neighbors(r, c):
        for dr, dc in dirs:
            nr, nc = r+dr, c+dc
            if in_bounds(nr, nc):
                yield nr, nc

