            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                yield nr, nc

    def check_global_connectivity():
        """
        Verifies that all currently known/potential white cells (state != 1) 
        form a single orthogonally connected group.
        """
        white_cells = []
        start_node = None

        for r in range(n):
            for c in range(n):
                if state[r][c] != 1:
                    white_cells.append((r, c))
                    if start_node is None:
                        start_node = (r, c)

        # If 0 or 1 white cells, it's trivially connected
        if len(white_cells) <= 1:
            return True

