        visited = set()
        stack = [start_node]

        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))

            for nr, nc in get_ortho_neighbors(r, c):
                if state[nr][nc] != 1 and (nr, nc) not in visited:
                    stack.append((nr, nc))

        # If we couldn't reach all white cells, the grid is disconnected
        return len(visited) == len(white_cells)

    def is_consistent(r, c, val):
        """
