                    if state[r][c] != 0:
                        continue

                    can_be_white = is_consistent(r, c, -1)
                    can_be_black = is_consistent(r, c, 1)

                    if not can_be_white and not can_be_black:
                        return False  # Contradiction found

                    if not can_be_white:
                        state[r][c] = 1
                        changed = True
                    elif not can_be_black:
                        state[r][c] = -1
                        changed = True
        return True

