        """
        # Step 1: Propagate known constraints
        if not propagate_constraints():
            return False

        # Step 2: Select unassigned cell (MRV Heuristic)
        # Choose the cell with the fewest valid options to fail fast.
        best_cell = None
        min_options = 3  # Max options is 2 (White/Black)

        for r in range(n):
            for c in range(n):
