    def get_valid_subsets(candidates, target):
        """
        Find all subsets of candidates that sum exactly to target.
        Uses iterative bitmask approach for efficiency with small sets (max 7 elements).
        Returns list of sets.
        """
        n = len(candidates)
        valid = []
        # Iterate through all 2^n subsets
        for mask in range(1 << n):
            s = 0
            subset = set()
            for i in range(n):
                if mask & (1 << i):
                    s += candidates[i]
                    subset.add(candidates[i])
            if s == target:
