        """Calculates current visibility count from (r, c)."""
        if grid[r][c] == -1: # Should never happen for a clue, but safety check
            return 0
        count = 1 # Self
        # Check 4 directions
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < n and grid[nr][nc] != -1:
                count += 1
                nr += dr
                nc += dc
        return count

    def check_connectivity():
