        Uses BFS/DFS. Returns False if disconnected.
        """
        white_cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 1]
        if not white_cells:
            return True # Trivial case or no whites yet (though clues imply whites)

        visited = set()
        stack = [white_cells[0]]
        visited.add(white_cells[0])

        while stack:
            r, c = stack.pop()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in visited and grid[nr][nc] == 1:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

        return len(visited) == len(white_cells)

    def propagate_constraints():
        """
        Applies human-like deductive logic to fill in obvious cells without guessing.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
