    # Cell states: 0 = UNKNOWN, 1 = WHITE, 2 = BLACK
    grid = [[0] * n for _ in range(n)]
    clues = {}

    # Initialize grid with clues (clues are always white)
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                grid[r][c] = 1
                clues[(r, c)] = data[r][c]

    DIRS = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def in_bounds(r, c):
        return 0 <= r < n and 0 <= c < n

    def analyze_direction(r, c, dr, dc):
        """
        Analyzes visibility in one direction from (r,c).
        Returns: (confirmed_whites, unknowns_ahead, is_blocked_by_black)
        Walks from (r,c)+direction until border or black cell.
        """
        nr, nc = r + dr, c + dc
        whites = 0
        unknowns = 0

        while in_bounds(nr, nc):
            cell = grid[nr][nc]
            if cell == 2:  # Black cell blocks view
                return whites, unknowns, True
            elif cell == 1:  # Known white
                whites += 1
            else:  # Unknown
                unknowns += 1
            nr += dr
            nc += dc

        return whites, unknowns, False  # Reached border

    def propagate():
        """
        Applies logical deduction rules until no further progress or contradiction.
        Returns: True if valid state, False if contradiction detected.
        """
        changed = True
        while changed:
            changed = False

            # --- Rule 1: Clue Visibility Constraints ---
            for (r, c), target_val in clues.items():
                current_visible = 1  # Include self
                max_additional = 0
                direction_data = []

                for dr, dc in DIRS:
                    w, u, blocked = analyze_direction(r, c, dr, dc)
                    direction_data.append((dr, dc, w, u, blocked))
                    current_visible += w
                    max_additional += u

                # Contradiction checks
                if current_visible > target_val:
                    return False
                if current_visible + max_additional < target_val:
                    return False

                # Case A: Clue is already satisfied (exact match)
                # All unknowns in line-of-sight MUST be black to prevent over-counting
                if current_visible == target_val:
                    for dr, dc, w, u, blocked in direction_data:
                        nr, nc = r + dr, c + dc
                        # Skip past known whites
                        for _ in range(w):
                            nr += dr
                            nc += dc
                        # Set remaining unknowns to black
                        for _ in range(u):
                            if grid[nr][nc] == 0:
                                grid[nr][nc] = 2
                                changed = True
                            elif grid[nr][nc] == 1:
                                return False  # Tried to shade a white cell
                            nr += dr
                            nc += dc

                # Case B: Need maximum possible visibility to reach target
                # All unknowns in sight MUST be white, and cell after must be black (if exists)
                elif current_visible + max_additional == target_val:
                    for dr, dc, w, u, blocked in direction_data:
                        nr, nc = r + dr, c + dc
                        # Skip past known whites
                        for _ in range(w):
                            nr += dr
                            nc += dc
                        # Force unknowns to be white
                        for _ in range(u):
                            if grid[nr][nc] == 0:
                                grid[nr][nc] = 1
                                changed = True
                            elif grid[nr][nc] == 2:
                                return False  # Needed white but found black
                            nr += dr
                            nc += dc
                        # Block the view immediately after the last required white
                        if in_bounds(nr, nc) and grid[nr][nc] == 0:
                            grid[nr][nc] = 2
                            changed = True
                        elif in_bounds(nr, nc) and grid[nr][nc] == 1:
                            return False  # Can't block here, it's white/clue

            # --- Rule 2: Black Cell Isolation (No Orthogonal Touching) ---
            newly_black = []
            for r in range(n):
                for c in range(n):
                    if grid[r][c] == 2:
                        for dr, dc in DIRS:
                            nr, nc = r + dr, c + dc
                            if in_bounds(nr, nc) and grid[nr][nc] == 0:
                                # Neighbor of black must be white
                                grid[nr][nc] = 1
                                changed = True
                            elif in_bounds(nr, nc) and grid[nr][nc] == 2:
                                return False  # Two blacks touching

            # --- Rule 3: White Connectivity (Single Component) ---
            white_cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 1]
            if white_cells:
                # BFS from first white cell, allowing passage through unknowns
                visited = [[False] * n for _ in range(n)]
                sr, sc = white_cells[0]
                queue = [(sr, sc)]
                visited[sr][sc] = True
                reachable_whites = 0

                while queue:
                    cr, cc = queue.pop(0)
                    if grid[cr][cc] == 1:
                        reachable_whites += 1
                    for dr, dc in DIRS:
                        nr, nc = cr + dr, cc + dc
                        if in_bounds(nr, nc) and not visited[nr][nc] and grid[nr][nc] != 2:
                            visited[nr][nc] = True
                            queue.append((nr, nc))

                # If we can't reach all existing white cells, puzzle is broken
                if reachable_whites != len(white_cells):
                    return False

        return True

    def solve_recursive():
        """
        Recursive backtracking solver with constraint propagation.
        Returns: Solved grid or None if no solution.
        """
        # Propagate constraints first
        if not propagate():
            return None

        # Find first unknown cell (could optimize with MRV heuristic here)
        unknown_cell = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    unknown_cell = (r, c)
                    break
            if unknown_cell:
                break

        # If no unknowns left, we have a solution
        if unknown_cell is None:
            return [row[:] for row in grid]

        r, c = unknown_cell

        # Try WHITE first (typically maintains connectivity better)
        for value in [1, 2]:
            # Save state for backtracking
            backup = [row[:] for row in grid]
            grid[r][c] = value

            result = solve_recursive()
            if result is not None:
                return result

            # Restore state
            for i in range(n):
                for j in range(n):
                    grid[i][j] = backup[i][j]

        return None

    # Execute solver
    solution = solve_recursive()

    if solution is None:
        return "No Solution"

    # Format output according to specifications
    output = []
    for r in range(n):
        row = []
        for c in range(n):
            if solution[r][c] == 2:
                row.append('B')
            elif (r, c) in clues:
                row.append(clues[(r, c)])
            else:
                row.append(None)
        output.append(row)

    return output

