        if r < N-1: neigh.append((r+1, c))
        if c > 0: neigh.append((r, c-1))
        if c < N-1: neigh.append((r, c+1))
        return neigh

    def check_connectivity(shaded_set):
        if not shaded_set: return True
        # BFS/DFS to check if all shaded cells are connected
        start = next(iter(shaded_set))
        stack = [start]
        visited = {start}
        while stack:
            curr = stack.pop()
            for neigh in get_neighbors(curr):
                if neigh in shaded_set and neigh not in visited:
                    visited.add(neigh)
                    stack.append(neigh)
