            for p_coords in placements[rid][t_type]:
                # Check 2x2 constraint locally
                if not check_no_2x2(p_coords, current_shaded):
                    continue

                # Check Connectivity
                # New shaded set
                new_shaded = current_shaded | p_coords

                # Optimization: 
                # If current_shaded is not empty, the new piece must connect to it.
                # If it doesn't, we create disjoint islands (unless this is the first piece).
                # However, future pieces could bridge them? 
                # Rule: "All shaded cells... connected". Usually implies the final state.
                # But pruning early: if we have two separate groups now, and they are in different regions
                # that are not adjacent to any unassigned region that could bridge them... complex.
                # Simple check: New piece must touch existing shaded mass, OR this is the first piece.
                is_connected = True
                if current_shaded:
