                    for cell in p_coords:
                        for neigh in get_neighbors(cell):
                            if neigh in current_shaded:
                                touches = True
                                break
                        if touches: break
                    if not touches:
                        # It's possible we are filling a hole surrounded by unassigned regions?
                        # But strict connectivity usually requires incremental connection for solvability.
                        # Let's allow it only if we haven't sealed off the old group.
                        # For now, strict requirement: Must touch.
                        is_connected = False 

                if not is_connected:
                    continue

                # Full connectivity check (expensive, but safe)
                # Can optimize: if it touches, and old was connected, new is connected.
                # Exception: if new piece bridges two parts? No, new is one component.
                # So if new touches old, union is connected.

                current_assignment[rid] = (t_type, p_coords)
                if backtrack(idx + 1, current_assignment, new_shaded):
                    return True

                del current_assignment[rid]

        return False

    # Execute
    initial_assignment = {}
    initial_shaded = set()

    # Sort regions to handle smallest/most constrained first?
    # Simple sort by size (ascending) often helps.
    region_ids.sort(key=lambda rid: len(regions_map[rid]))

    if backtrack(0, initial_assignment, initial_shaded):
