            for orientation in orientations:
                # Try to fit this orientation anchored at each cell in the region
                for anchor_r, anchor_c in cells_list:
                    placed_cells = set()
                    valid = True
                    for dr, dc in orientation:
                        nr, nc = anchor_r + dr, anchor_c + dc
                        if (nr, nc) not in region_cells:
                            valid = False
                            break
                        placed_cells.add((nr, nc))

                    if valid and len(placed_cells) == 4:
                        placements.append((t_type, frozenset(placed_cells)))

        return placements

    region_placements = {}
    for rid in region_ids:
        region_placements[rid] = get_placements(regions[rid])

    # Step 4: Backtracking solver with constraint propagation
    solution = {}  # region_id -> (type, cells_set)

    def get_shaded_cells():
        shaded = set()
        for _, (_, cells) in solution.items():
            shaded.update(cells)
        return shaded

    def check_no_2x2(new_cells, current_shaded):
        """Check if adding new_cells creates any 2x2 shaded block"""
        combined = current_shaded | new_cells
        for r, c in new_cells:
            # Check the 2x2 blocks that include (r,c)
            for dr in [-1, 0]:
                for dc in [-1, 0]:
                    br, bc = r + dr, c + dc
                    if 0 <= br < rows-1 and 0 <= bc < cols-1:
                        block = {(br, bc), (br, bc+1), (br+1, bc), (br+1, bc+1)}
                        if block <= combined:  # subset
                            return False
        return True

    def check_connectivity(new_cells, current_shaded):
        """Check if all shaded cells form a single connected component"""
        if not current_shaded:
            return True

        combined = current_shaded | new_cells

        # Find if new cells connect to old shaded area
        # Or if old shaded area remains connected and touches new area
        start = next(iter(combined))
        visited = set()
        queue = deque([start])
        visited.add(start)

        while queue:
            cr, cc = queue.popleft()
            for ndr, ndc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = cr+ndr, cc+ndc
                if (nr, nc) in combined and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == len(combined)

    def solve_recursive(idx):
        if idx == len(region_ids):
            return True

        rid = region_ids[idx]

        # Get forbidden types from already assigned neighbors
        forbidden_types = set()
        for nrid in adjacency.get(rid, []):
            if nrid in solution:
                forbidden_types.add(solution[nrid][0])

        current_shaded = get_shaded_cells()

        # Try each valid placement
        for p_type, p_cells in region_placements[rid]:
            if p_type in forbidden_types:
                continue

            # Convert to regular set for operations
            p_cells_set = set(p_cells)

            # Constraint: No 2x2 block
            if not check_no_2x2(p_cells_set, current_shaded):
                continue

            # Constraint: Connectivity
            if not check_connectivity(p_cells_set, current_shaded):
                continue

            # Assign
            solution[rid] = (p_type, p_cells_set)

            if solve_recursive(idx + 1):
                return True

            del solution[rid]

        return False

    # Sort regions by number of placements (MRV heuristic) for efficiency
    region_ids.sort(key=lambda x: len(region_placements[x]))

    if not solve_recursive(0):
        return "No Solution"

    # Build output grid
    output = [[None for _ in range(cols)] for _ in range(rows)]
    for rid, (t_type, cells) in solution.items():
        for r, c in cells:
            output[r][c] = t_type

    return output

