                    elif cell_val == -1:
                        unknown_cells.append((nr, nc))

                num_unknowns = len(unknown_cells)

                # Pruning Rule 1: Too many blacks already placed
                if black_count > target:
                    return False

                # Pruning Rule 2: Not enough cells left to reach target
                if black_count + num_unknowns < target:
                    return False

                # Deduction Rule 1: Target reached, rest must be White
                if black_count == target:
                    for ur, uc in unknown_cells:
                        if grid[ur][uc] != 0:
                            grid[ur][uc] = 0
                            changed = True

                # Deduction Rule 2: Must fill all remaining unknowns to reach target (force Black)
                elif black_count + num_unknowns == target:
                    for ur, uc in unknown_cells:
                        if grid[ur][uc] != 1:
                            grid[ur][uc] = 1
                            changed = True
        return True

    def backtrack():
        """
        Recursive depth-first search with backtracking.
        Selects an unknown cell, tries both colors, and propagates constraints.
        """
        # Find the next unknown cell (simple left-to-right, top-to-bottom scan)
        target_cell = None
        for r in range(rows):
