        for color in (1, 0):
            # Save state for backtracking
            prev_state = [row[:] for row in grid]

            grid[r][c] = color

            # Apply constraint propagation after assignment
            if propagate() and backtrack():
                return True

            # Restore state if this branch failed
            for i in range(rows):
                for j in range(cols):
                    grid[i][j] = prev_state[i][j]

        return False

    # Execute solver
    if propagate() and backtrack():
        # Format output according to specifications: 'B' for black, None for white
        result_grid = [
            ['B' if grid[r][c] == 1 else None for c in range(cols)]
