def solve(observation):
    """
    Solves the 3x3 neighborhood counting puzzle using constraint propagation
    and backtracking search with MRV (Minimum Remaining Values) heuristic.
    """
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows > 0 else 0

    # Cell states: -1 = unknown/empty, 0 = white, 1 = black
    grid = [[-1 for _ in range(cols)] for _ in range(rows)]

    # Precompute constraints: each numbered cell defines a constraint over its 3x3 neighborhood
    constraints = []  # List of (target_value, [(neighbor_r, neighbor_c), ...])
    # Reverse mapping: for each cell, which constraint indices does it participate in?
    cell_constraints = [[[] for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                target = data[r][c]
                neighbors = []
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            neighbors.append((nr, nc))

                idx = len(constraints)
                constraints.append((target, neighbors))
                for nr, nc in neighbors:
                    cell_constraints[nr][nc].append(idx)

    def propagate(affected_constraints=None):
        """
        Applies constraint propagation rules until no further deductions can be made.
        Returns False if a contradiction is detected, True otherwise.
        Uses a queue to process only constraints affected by recent changes.
        """
        if affected_constraints is None:
            # Initial full propagation
            queue = list(range(len(constraints)))
        else:
            queue = list(affected_constraints)

        processed = set()

        while queue:
            cid = queue.pop(0)
            if cid in processed:
                continue
            processed.add(cid)

            target, neighbors = constraints[cid]

            # Count current state of this constraint's neighborhood
            black_cnt = 0
            unknown_cnt = 0
            unknown_cells = []

            for nr, nc in neighbors:
                val = grid[nr][nc]
                if val == 1:
                    black_cnt += 1
                elif val == -1:
                    unknown_cnt += 1
                    unknown_cells.append((nr, nc))

            # Contradiction checks
            if black_cnt > target:
                return False  # Too many black cells
            if black_cnt + unknown_cnt < target:
                return False  # Not enough cells left to reach target

            # Deduction Rule 1: If remaining unknowns exactly fill the gap, they must be black
            if black_cnt + unknown_cnt == target and unknown_cnt > 0:
                for nr, nc in unknown_cells:
                    if grid[nr][nc] == -1:
                        grid[nr][nc] = 1
                        # Add all constraints involving this newly set cell to queue
                        for next_cid in cell_constraints[nr][nc]:
                            if next_cid not in processed:
                                queue.append(next_cid)

            # Deduction Rule 2: If target already met, all remaining unknowns must be white
            elif black_cnt == target and unknown_cnt > 0:
                for nr, nc in unknown_cells:
                    if grid[nr][nc] == -1:
                        grid[nr][nc] = 0
                        for next_cid in cell_constraints[nr][nc]:
                            if next_cid not in processed:
                                queue.append(next_cid)

        return True

    def select_unassigned_variable():
        """
        MRV (Minimum Remaining Values) heuristic with degree heuristic tie-breaker.
        Selects the unknown cell that is most constrained (appears in tightest constraints).
        Returns (row, col) or None if no unknowns remain.
        """
        best_cell = None
        best_score = float('-inf')

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != -1:
                    continue

                # Calculate constraint tightness score for this cell
                score = 0
                for cid in cell_constraints[r][c]:
                    target, neighbors = constraints[cid]

                    b_cnt = sum(grid[nr][nc] == 1 for nr, nc in neighbors)
                    u_cnt = sum(grid[nr][nc] == -1 for nr, nc in neighbors)

                    # Higher score if constraint is nearly satisfied or forces color
                    if u_cnt == 0:
                        continue

                    remaining = target - b_cnt
                    if remaining == 0:
                        # This cell MUST be white (highly constrained)
                        score += 1000
                    elif remaining == u_cnt:
                        # This cell MUST be black (highly constrained)
                        score += 1000
                    elif remaining < 0 or remaining > u_cnt:
                        # Should have been caught by propagation, but safety check
                        score -= 10000
                    else:
                        # Prefer cells where the choice matters more (fewer options effectively)
                        # Add based on how "tight" the ratio is
                        tightness = abs(remaining / u_cnt - 0.5) * 2  # 0 to 1 scale
                        score += tightness * 100

                # Tie-breaker: prefer cells with more constraints (degree heuristic)
                score += len(cell_constraints[r][c]) * 10

                if score > best_score:
                    best_score = score
                    best_cell = (r, c)

        return best_cell

    def backtrack():
        """
        Recursive backtracking search with forward checking via propagation.
        """
        # First, run full propagation to handle any deterministic deductions
        if not propagate():
            return False

        # Select next cell to assign using MRV
        cell = select_unassigned_variable()

        if cell is None:
            # No unknown cells left - solution found!
            return True

        r, c = cell

        # Try both values; order can affect efficiency (try 1 first as often more constrained)
        for value in (1, 0):
            # Save state for restoration (though we'll restore explicitly)
            grid[r][c] = value

            # Only re-propagate constraints affected by this cell change
            affected = set(cell_constraints[r][c])
            if propagate(list(affected)):
                if backtrack():
                    return True

            # Undo assignment
            grid[r][c] = -1

        return False

    # Execute solver
    if backtrack():
        # Format output: 'B' for black (1), None for white (0)
        result = []
        for r in range(rows):
            row_res = []
            for c in range(cols):
                if grid[r][c] == 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            result.append(row_res)
        return result
    else:
        return "No Solution"

