OBSERVATION = {
    'data': [
        [None, 4, 4, None, None, 1, None],
        [None, None, None, None, 3, None, None],
        [None, 9, 7, 4, 3, 5, None],
        [None, 6, None, 2, None, None, 5],
        [3, None, 5, None, None, 4, None],
        [None, None, None, None, 1, None, None],
        [3, None, None, 2, None, None, 1]
    ]
}

def solve(observation):
    """
    Solves the grid puzzle based on 3x3 neighborhood constraints.
    Returns the grid with 'B' for Black and None for White.
    """
    data = observation['data']
    if not data:
        return "No Solution"

    ROWS = len(data)
    COLS = len(data[0])

    # State representation: -1 = Unknown, 0 = White, 1 = Black
    grid = [[-1] * COLS for _ in range(ROWS)]

    # Structure to hold clue information
    # Clue: {target_value, list_of_neighbor_coordinates}
    clues = []
    # Map from cell (r,c) to list of clue indices that constrain this cell
    cell_constraints = defaultdict(list)

    # Parse clues and build dependency graph
    for r in range(ROWS):
        for c in range(COLS):
            val = data[r][c]
            if val is not None:
                neighbors = []
                # Generate 3x3 neighborhood coordinates
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < ROWS and 0 <= nc < COLS:
                            neighbors.append((nr, nc))

                clue_index = len(clues)
                clues.append({
                    'r': r, 'c': c,
                    'target': val,
                    'neighbors': neighbors
                })

                # Register this clue for all its neighbors
                for pos in neighbors:
                    cell_constraints[pos].append(clue_index)

    def propagate(current_grid, queue):
        """
        Performs constraint propagation using a queue of updated cells.
        Returns False if a contradiction is detected, True otherwise.
        """
        while queue:
            r, c = queue.popleft()

            # Check every clue that involves the updated cell (r, c)
            for clue_id in cell_constraints[(r, c)]:
                clue = clues[clue_id]
                target = clue['target']
                neighbors = clue['neighbors']

                current_black = 0
                current_unknown = 0
                unknown_cells = []

                # Analyze the neighborhood state
                for nr, nc in neighbors:
                    state = current_grid[nr][nc]
                    if state == 1:
                        current_black += 1
                    elif state == -1:
                        current_unknown += 1
                        unknown_cells.append((nr, nc))

                # Contradiction 1: Too many black cells
                if current_black > target:
                    return False

                # Contradiction 2: Not enough cells left to reach target
                if current_black + current_unknown < target:
                    return False

                # Inference 1: Target met, rest must be White
                if current_black == target:
                    for ur, uc in unknown_cells:
                        if current_grid[ur][uc] != 0:
                            current_grid[ur][uc] = 0
                            queue.append((ur, uc))

                # Inference 2: Must fill all remaining to reach target (all Black)
                elif current_black + current_unknown == target:
                    for ur, uc in unknown_cells:
                        if current_grid[ur][uc] != 1:
                            current_grid[ur][uc] = 1
                            queue.append((ur, uc))

        return True

    def deep_search(current_grid):
        """
        Recursive depth-first search with backtracking.
        Picks an unknown cell, guesses, and propagates.
        """
        # 1. Find the next unknown cell to branch on
        # Heuristic: Simple left-to-right, top-to-bottom scan is sufficient for 7x7
        # given aggressive propagation pruning.
        target_cell = None
        for r in range(ROWS):
            for c in range(COLS):
                if current_grid[r][c] == -1:
                    target_cell = (r, c)
                    break
            if target_cell:
                break

        # Base Case: No unknown cells means puzzle is solved
        if not target_cell:
            return current_grid

        r, c = target_cell

        # 2. Try assigning values (Black first, then White)
        for value in [1, 0]:
            # Create a copy of the grid for this branch
            new_grid = [row[:] for row in current_grid]
            new_grid[r][c] = value

            # Initialize propagation queue with the newly assigned cell
            q = deque()
            q.append((r, c))

            # Propagate constraints
            if propagate(new_grid, q):
                # If valid, recurse deeper
                result = deep_search(new_grid)
                if result:
                    return result

        # 3. Both values led to contradiction (or dead end)
        return None

    # --- Initialization & Bootstrapping ---
    # Handle edge cases where clues force immediate actions (e.g., target 0 or max neighbors)
    # without needing a guess to trigger propagation.
    init_queue = deque()
    for clue in clues:
        t = clue['target']
        n_count = len(clue['neighbors'])

        # If target is 0, all neighbors must be White
        if t == 0:
            for r, c in clue['neighbors']:
                if grid[r][c] == -1:
                    grid[r][c] = 0
                    init_queue.append((r, c))
