def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows > 0 else 0

    # State: -1 = unknown, 0 = white, 1 = black
    state = [[-1] * cols for _ in range(rows)]

    # Precompute clues and their neighborhoods
    clues = []  # List of (r, c, target_value, neighbors_list)
    cell_to_clues = {}  # Map (r,c) -> list of indices into clues

    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
