                clues.append({
                    'r': r, 
                    'c': c, 
                    'target': data[r][c],
                    'neighbors': neighbors,
                    'current': 0,
                    'unknown': len(neighbors)
                })

                for nr, nc in neighbors:
                    key = (nr, nc)
                    if key not in cell_to_clues:
                        cell_to_clues[key] = []
                    cell_to_clues[key].append(clue_idx)

    def get_neighbors(r, c):
        """Get valid 3x3 neighborhood coordinates"""
        res = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    res.append((nr, nc))
        return res

    def assign(r, c, val, clues_state):
        """
        Assign value (0=white, 1=black) to cell (r,c).
        Returns False if contradiction detected, True otherwise.
        Updates clues_state current/unknown counts.
        """
        if state[r][c] != -1:
            return state[r][c] == val

        state[r][c] = val

        # Update all clues that include this cell
        if (r, c) in cell_to_clues:
            for idx in cell_to_clues[(r, c)]:
                clue = clues_state[idx]
                clue['unknown'] -= 1
                if val == 1:
                    clue['current'] += 1

        return True

    def unassign(r, c, clues_state):
        """Reverse assignment"""
        old_val = state[r][c]
        state[r][c] = -1

        if (r, c) in cell_to_clues:
            for idx in cell_to_clues[(r, c)]:
                clue = clues_state[idx]
                clue['unknown'] += 1
                if old_val == 1:
                    clue['current'] -= 1

    def propagate(clues_state):
        """
        Constraint propagation using deductive rules:
        1. If current > target: FAIL
        2. If current + unknown < target: FAIL  
        3. If current == target: all unknown neighbors must be WHITE (0)
        4. If current + unknown == target: all unknown neighbors must be BLACK (1)

        Returns True if consistent, False if contradiction.
        """
        queue = set(range(len(clues)))
        processed = set()

        while queue:
            idx = queue.pop()
            if idx in processed:
                continue
            processed.add(idx)

            clue = clues_state[idx]
            curr = clue['current']
            unk = clue['unknown']
            tgt = clue['target']

            # Check failures
            if curr > tgt:
                return False
            if curr + unk < tgt:
                return False

            # Deduction: all remaining must be white
            if curr == tgt and unk > 0:
                for nr, nc in clue['neighbors']:
                    if state[nr][nc] == -1:
                        if not assign(nr, nc, 0, clues_state):
                            return False
                        # Add affected clues to queue
                        if (nr, nc) in cell_to_clues:
                            for nidx in cell_to_clues[(nr, nc)]:
                                if nidx != idx:
                                    queue.add(nidx)

            # Deduction: all remaining must be black
            elif curr + unk == tgt and unk > 0:
                for nr, nc in clue['neighbors']:
                    if state[nr][nc] == -1:
                        if not assign(nr, nc, 1, clues_state):
                            return False
                        if (nr, nc) in cell_to_clues:
                            for nidx in cell_to_clues[(nr, nc)]:
                                if nidx != idx:
                                    queue.add(nidx)

        return True

    def select_unassigned_variable():
        """
        MRV (Minimum Remaining Values) heuristic with degree heuristic tiebreaker.
        Prefer cells involved in most constrained clues (smallest slack).
        """
        best_cell = None
        best_score = float('inf')

        for r in range(rows):
            for c in range(cols):
                if state[r][c] == -1:
                    # Calculate constraint tightness: min(slack) over all clues containing this cell
                    # Slack = target - current (how many more blacks needed)
                    # Or use: number of clues forcing this cell?

                    # Simple MRV: check if any clue forces this cell
                    score = 0
                    if (r, c) in cell_to_clues:
                        min_slack = float('inf')
                        max_slack = 0
                        for idx in cell_to_clues[(r, c)]:
                            clue = clues[idx]
                            needed = clue['target'] - clue['current']
                            available = clue['unknown']
                            if needed < 0: needed = 0
                            if needed > available: needed = available
                            slack = available - needed
                            min_slack = min(min_slack, slack)
                            max_slack = max(max_slack, needed)

                        # Prefer cells where clues are tighter (less flexibility)
                        score = (min_slack, -len(cell_to_clues[(r, c)]))
                    else:
                        score = (float('inf'), 0)

                    if score < best_score:
                        best_score = score
                        best_cell = (r, c)

        return best_cell

    def backtrack():
        """Recursive backtracking with constraint propagation"""
        # First, try to propagate existing assignments
        if not propagate(clues):
            return False

        # Check if complete
        for r in range(rows):
            for c in range(cols):
                if state[r][c] == -1:
                    # Found unassigned variable
                    cell = select_unassigned_variable()
                    if cell is None:
                        cell = (r, c)
                    cr, cc = cell

                    # Try both values (order: black first then white, or based on heuristics)
                    # Actually, let's check which value is more constrained
                    for val in [1, 0]:  # Try black first, often more constrained
                        # Save state for restoration
                        saved_clues = [{'current': c['current'], 'unknown': c['unknown']} for c in clues]

                        if assign(cr, cc, val, clues):
                            if backtrack():
                                return True
                            unassign(cr, cc, clues)

                        # Restore clue states
                        for i, sc in enumerate(saved_clues):
                            clues[i]['current'] = sc['current']
                            clues[i]['unknown'] = sc['unknown']

                    return False

        # All variables assigned and propagated successfully
        return True

    # Initialize by processing initial clues (like 0s forcing whites)
    if not backtrack():
        return "No Solution"

    # Format output: 'B' for black (1), None for white (0)
    result = []
    for r in range(rows):
        row_result = []
        for c in range(cols):
            if state[r][c] == 1:
                row_result.append('B')
            else:
                row_result.append(None)
        result.append(row_result)

    return result

