# Cell states
UNKNOWN = 0
BLACK = 1
WHITE = -1

def solve(observation):
    """
    Solves a Nonogram puzzle using constraint propagation and backtracking.
    Returns the solved grid as a list of lists with 'B' and None, or "No Solution".
    """
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']

    if not row_clues or not col_clues:
        return "No Solution"

    height = len(row_clues)
    width = len(col_clues)

    # Initialize grid with UNKNOWNs
    grid = [[UNKNOWN] * width for _ in range(height)]

    # Attempt to solve with propagation and backtracking
    if _solve_grid(grid, row_clues, col_clues, height, width):
        return _format_output(grid)
    return "No Solution"

def _solve_grid(grid, row_clues, col_clues, height, width):
    """
    Main solving routine. Applies constraint propagation until stuck,
    then uses backtracking search.
    """
    # Constraint Propagation Loop
    changed = True
    while changed:
        changed = False

        # Process all rows
        for r in range(height):
            line = grid[r][:]
            new_line = _solve_line(line, row_clues[r])
            if new_line is None:
                return False  # Contradiction found

            if new_line != line:
                grid[r] = new_line
                changed = True

        # Process all columns
        for c in range(width):
            line = [grid[r][c] for r in range(height)]
            new_line = _solve_line(line, col_clues[c])
            if new_line is None:
                return False  # Contradiction found

            # Apply changes back to column
            for r in range(height):
                if grid[r][c] != new_line[r]:
                    grid[r][c] = new_line[r]
                    changed = True

    # Check if completely solved
    if _is_completely_filled(grid, height, width):
        return True

    # Need to backtrack - find best cell to guess
    # Heuristic: pick the unknown cell with most constraints (or simply first found)
    best_cell = None
    min_options = float('inf')

    for r in range(height):
        for c in range(width):
            if grid[r][c] == UNKNOWN:
                # Count how many possibilities this cell has in its row/col
                # Simple heuristic: just take first unknown for now, 
                # or count line possibilities for better pruning
                if best_cell is None:
                    best_cell = (r, c)

    if best_cell is None:
        return True  # Should be caught by is_completely_filled, but safety check

    r, c = best_cell

    # Try BLACK first (often more constraining)
    for val in [BLACK, WHITE]:
        # Create a deep copy of grid for this branch
        grid_copy = [row[:] for row in grid]
        grid_copy[r][c] = val

        if _solve_grid(grid_copy, row_clues, col_clues, height, width):
            # Copy solution back to original grid reference
            for i in range(height):
                for j in range(width):
                    grid[i][j] = grid_copy[i][j]
            return True

    return False

def _solve_line(line, clues):
    """
    Given a line (row or col) with current states and target clues,
    returns the updated line with newly deduced cells, or None if impossible.
    Uses exhaustive generation of valid permutations with pruning.
    """
    length = len(line)

    # Handle empty clue (all white)
    if not clues:
        # All cells must be white
        if any(c == BLACK for c in line):
            return None
        return [WHITE] * length

    # Generate all valid permutations for this line given current state
    possibilities = list(_generate_possibilities(line, clues, 0, 0, []))

    if not possibilities:
        return None  # No valid arrangement exists - contradiction

    # Determine definitive cells by intersecting all possibilities
    result = line[:]
    for i in range(length):
        if result[i] != UNKNOWN:
            continue

        can_be_black = False
        can_be_white = False

        for poss in possibilities:
            if poss[i] == BLACK:
                can_be_black = True
            else:
                can_be_white = True

            if can_be_black and can_be_white:
                break  # Unknown remains unknown

        if can_be_black and not can_be_white:
            result[i] = BLACK
        elif can_be_white and not can_be_black:
            result[i] = WHITE
        # Else remains UNKNOWN

    return result

def _generate_possibilities(line, clues, pos, clue_idx, current):
    """
    Generator that yields all valid line configurations (as lists of BLACK/WHITE)
    that satisfy the clues and don't conflict with known cells in 'line'.
    Uses recursive backtracking with pruning.
    """
    length = len(line)

    # Base case: all clues placed
    if clue_idx == len(clues):
        # Remaining cells must all be WHITE (or compatible with WHITE)
        remaining = length - pos
        # Check if any remaining cell is forced BLACK
        for i in range(pos, length):
            if line[i] == BLACK:
                return  # Invalid: forced black cell in trailing whitespace
        yield current + [WHITE] * remaining
        return

    current_clue = clues[clue_idx]
    remaining_clues = clues[clue_idx+1:]

    # Minimum space needed for remaining clues including gaps
    min_space_needed = sum(remaining_clues) + len(remaining_clues)
    # Current clue size
    block_size = current_clue

    # Maximum starting position for current block such that remaining clues fit
    # We need: start + block_size + (1 if more clues else 0) + min_space_for_rest <= length
    # Actually: start + block_size <= length - min_space_needed - (0 if last else 1?) 
    # Gap handling: if not last clue, we need at least 1 space after this block before next
    required_after = min_space_needed + (1 if clue_idx < len(clues) - 1 else 0)
    max_start = length - required_after - block_size + 1  # inclusive bound adjustment

    # Ensure we don't go out of bounds
    if max_start < pos:
        max_start = pos - 1  # Will cause loop to not execute if invalid

    for start in range(pos, max_start + 1):
        # Validate placing block at [start, start+block_size)
        valid = True

        # Check cells that must be white in the gap before this block (if any)
        # The gap is from 'pos' to 'start-1'. These must be white.
        for i in range(pos, start):
            if line[i] == BLACK:
                valid = False
                break

        if not valid:
            continue

        # Check cells that must be black in the block
        for i in range(start, start + block_size):
            if i >= length or line[i] == WHITE:
                valid = False
                break

        if not valid:
            continue

        # Check cell immediately after block (if not end of line and more clues follow)
        # This cell must be white (separator)
        next_pos = start + block_size
        if clue_idx < len(clues) - 1:
            if next_pos < length and line[next_pos] == BLACK:
                valid = False

        if not valid:
