    def count_visible(sequence):
        """Counts how many buildings are visible from the start of the sequence."""
        visible = 0
        current_max = 0
        for height in sequence:
            if height > current_max:
                visible += 1
                current_max = height
        return visible

    def get_valid_permutation_domains(line_domains, clue):
        """
        Given a list of sets representing possible values for each cell in a line,
        and a visibility clue, returns a new list of sets containing ONLY the values
        that appear in at least one valid complete permutation satisfying the clue.
        Returns None if no valid permutation exists (contradiction).
        """
        valid_values = [set() for _ in range(N)]
        found_valid = False

        # Early exit if any domain is empty
        for d in line_domains:
            if not d:
                return None

        # Iterate through all permutations of 1..N
        # For N=6, this is 720 iterations, which is computationally trivial
        # and provides maximum constraint propagation power.
        for perm in itertools.permutations(range(1, N + 1)):

            # Check if permutation fits current domains
            fits_domain = True
            for i in range(N):
                if perm[i] not in line_domains[i]:
                    fits_domain = False
                    break

