        Applies constraint propagation until no further changes can be made.
        Implements Naked Singles, Hidden Singles, and Line (Permutation) Pruning.
        Returns False if a contradiction is detected, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # --- 1. Naked Singles ---
            # If a cell has one value, remove it from all peers in its row and column
            for r in range(N):
