                        break
                if start_node: break

        if not start_node:
            return [] # Should not happen if valid

        path = [start_node]
        current = start_node
        prev = None
        max_steps = (H+1)*W + H*(W+1) # Safety break

        while len(path) <= max_steps:
            cr, cc = current
            next_node = None
            candidates = []

            # Check neighbors
            if cc < W and h_edges[cr][cc] == 1 and (cr, cc+1) != prev:
                candidates.append((cr, cc+1))
            if cc > 0 and h_edges[cr][cc-1] == 1 and (cr, cc-1) != prev:
                candidates.append((cr, cc-1))
            if cr < H and v_edges[cr][cc] == 1 and (cr+1, cc) != prev:
                candidates.append((cr+1, cc))
            if cr > 0 and v_edges[cr-1][cc] == 1 and (cr-1, cc) != prev:
                candidates.append((cr-1, cc))

            if not candidates:
                break # Broken path or end

            next_node = candidates[0]

            if next_node == start_node and len(path) > 2:
                path.append(start_node) # Close loop
                return path

            path.append(next_node)
            prev = current
            current = next_node

        return [] # Invalid loop found

    result = solve_search()
    if result:
        return str(result)
    return "No Solution"

