            regions[reg_id].append((r, c))

    num_regions = len(regions)

    # State tracking
    # possible_stars[r][c]: Boolean, True if placing a star at (r,c) is still valid
    possible_stars = [[True] * n for _ in range(n)]

    # Counters for constraints
    # stars_in_row[r]: number of stars placed in row r (-1 means unknown/placed, but we track counts)
    # We'll use sets for placed stars

    def get_neighbors(r, c):
        """Returns list of neighboring cells (including diagonals)."""
        neighbors = []
        for dr in [-1, 0, 1]:
