                if 0 <= nr < n and 0 <= nc < n:
                    neighbors.append((nr, nc))
        return neighbors

    def eliminate(r, c):
        """Marks (r,c) as impossible for a star. Returns False if contradiction detected."""
        if not possible_stars[r][c]:
            return True # Already eliminated
        possible_stars[r][c] = False
        return True

    def propagate(placed_stars):
        """
        Applies constraint propagation rules.
        Returns False if a contradiction is found (e.g., row has 0 possible spots left but needs 1).
        Updates possible_stars grid.
        """
        changed = True
        while changed:
