            # (Handled during placement, but good to re-verify or handle implicit logic)

            # Rule: Naked Singles / Forced Moves
            # If a row/col/reg has only 1 possible spot, place star there.
            # Note: Placing a star triggers elimination of neighbors.

            # Check Rows
            for r in range(n):
                # Check if star already in row
                has_star = any((r, c) in placed_stars for c in range(n))
                if has_star:
