            opts = [(r, c) for (r, c) in cells if possible_stars[r][c]]
            if len(opts) < best_count:
                best_count = len(opts)
                best_options = opts
                target_type = 'reg'

        if not best_options:
            return None # Should have been caught by propagate, but safety check

        # 4. Try each option
        # Sort options? Maybe not needed for 6x6.
        for (r, c) in best_options:
