        for bc in range(0, cols, box_w):
            box = [(r, c) for r in range(br, br + box_h) for c in range(bc, bc + box_w)]
            unit_list.append(box)

    # Map each cell to its units and peers
    units = { (r, c): [] for r in range(rows) for c in range(cols) }
    peers = { (r, c): set() for r in range(rows) for c in range(cols) }

    for u in unit_list:
        for cell in u:
            units[cell].append(u)
            for other in u:
                if other != cell:
                    peers[cell].add(other)

    def initialize():
        """Initialize possible values dictionary."""
        values = { (r, c): set(range(1, rows + 1)) for r in range(rows) for c in range(cols) }
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] is not None:
                    if not assign(values, (r, c), grid[r][c]):
                        return False
        return values

    def assign(values, cell, digit):
        """Eliminate all other values from values[cell] and propagate."""
        other_values = values[cell] - {digit}
        if all(eliminate(values, cell, d) for d in other_values):
            return values
        else:
            return False

    def eliminate(values, cell, digit):
        """Eliminate digit from values[cell]; propagate when <= 2 values remain."""
        if digit not in values[cell]:
            return values  # Already eliminated
        values[cell] = values[cell] - {digit}

        # Rule 1: If a cell has one value left, eliminate it from peers
        if len(values[cell]) == 0:
            return False  # Contradiction
        elif len(values[cell]) == 1:
            d = next(iter(values[cell]))
            if not all(eliminate(values, peer, d) for peer in peers[cell]):
                return False

        # Rule 2: If a unit has only one place for a value, put it there
        for u in units[cell]:
            d_places = [c for c in u if digit in values[c]]
            if len(d_places) == 0:
                return False  # Contradiction
            elif len(d_places) == 1:
                if not assign(values, d_places[0], digit):
                    return False
        return values

    def search(values):
        """Using depth-first search and propagation, try all possible values."""
        if values is False:
            return False  # Failed earlier
        if all(len(values[cell]) == 1 for cell in values):
            return values  # Solved!

        # Choose the unfilled cell with fewest possibilities (MRV heuristic)
        n, cell = min((len(values[cell]), cell) for cell in values if len(values[cell]) > 1)

        for digit in list(values[cell]):
            # Deep copy simulation by re-initializing or using copy module logic manually for speed
            # For pure Python without imports, we can use a recursive approach on copies of sets
            new_values = {k: set(v) for k, v in values.items()}
            result = search(assign(new_values, cell, digit))
            if result:
                return result
        return False

    vals = initialize()
    if not vals:
        return "No Solution"

    solution = search(vals)
    if not solution:
        return "No Solution"

    # Format output
    final_grid = [[solution[(r, c)].pop() for c in range(cols)] for r in range(rows)]
    return str(final_grid)

