                if has_tent:
                    continue

                # Find valid candidates for this specific tree's tent
                candidates = [(nr, nc) for nr, nc in get_neighbors(tr, tc) if g[nr][nc] == '']

                if len(candidates) == 0:
                    return False  # Tree has no place for a tent
                if len(candidates) == 1:
                    nr, nc = candidates[0]
                    g[nr][nc] = 't'
                    changed = True

