    def dfs(current_grid):
        """Depth-first search with constraint propagation."""
        # Make a deep copy to avoid mutating parent states incorrectly during recursion
        # Note: In Python, lists are mutable, so we copy the grid structure
        g = [row[:] for row in current_grid]

        if not propagate(g):
