def solve(observation):
    """
    Solves the Tents and Trees puzzle using constraint propagation and backtracking.
    Mirrors human deductive logic: line counting, forced moves, and spatial exclusion.
    """

    # --- 1. Initialization & Parsing ---
    raw_grid = observation['tree']
    R = len(raw_grid)
    C = len(raw_grid[0])
    row_targets = observation['row_tent_counts']
    col_targets = observation['col_tent_counts']

    # Grid state constants
    UNKNOWN = 0
    TENT = 1
    GRASS = 2
    TREE = 3

    # Initialize grid and locate trees
    grid = [[UNKNOWN] * C for _ in range(R)]
    trees = []
    for r in range(R):
        for c in range(C):
            if raw_grid[r][c] == 'T':
                grid[r][c] = TREE
                trees.append((r, c))

    def get_result_grid():
        """Formats the final grid into the required output string."""
        result_lines = []
        for r in range(R):
            line = ""
            for c in range(C):
                if grid[r][c] == TENT:
                    line += 't'
                else:
                    line += '.'
            result_lines.append(line)
        return "
