    def propagate():
        """
        Applies deterministic logical rules until no further progress can be made.
        Returns True if state is valid, False if a contradiction is found.
        """
        changed = True
        while changed:
            changed = False

            # Current counts for validation
            row_cur = [0] * R
            col_cur = [0] * C
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == TENT:
                        row_cur[r] += 1
                        col_cur[c] += 1

            # --- Rule A: Line Satisfiability (Row/Column Constraints) ---
            for r in range(R):
                need = row_targets[r] - row_cur[r]
                if need < 0: return False # Overfilled

                avail_cells = [(r, c) for c in range(C) if grid[r][c] == UNKNOWN]

                if need == 0:
                    # Row is full, rest must be grass
                    for c in range(C):
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = GRASS
                            changed = True
                elif need == len(avail_cells):
                    # Only exact spots left, force tents
                    for _, c in avail_cells:
                        grid[r][c] = TENT
                        changed = True

            for c in range(C):
                need = col_targets[c] - col_cur[c]
                if need < 0: return False

                avail_cells = [(r, c) for r in range(R) if grid[r][c] == UNKNOWN]

                if need == 0:
                    for r in range(R):
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = GRASS
                            changed = True
                elif need == len(avail_cells):
                    for r, _ in avail_cells:
                        grid[r][c] = TENT
                        changed = True

            # --- Rule B: Tree Pairing Constraints ---
            for tr, tc in trees:
                neighbors = []
                has_tent = False

