                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = tr + dr, tc + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        if grid[nr][nc] == TENT:
                            has_tent = True
                        elif grid[nr][nc] == UNKNOWN:
                            neighbors.append((nr, nc))

                if has_tent:
                    # Tree is happy, block other potential tent spots around it
                    for nr, nc in neighbors:
                        grid[nr][nc] = GRASS
                        changed = True
                else:
                    if len(neighbors) == 0:
                        return False # Tree has nowhere to go
                    if len(neighbors) == 1:
                        # Forced move: only one valid spot for this tree's tent
                        nr, nc = neighbors[0]
                        grid[nr][nc] = TENT
                        changed = True

            # --- Rule C: Tent Isolation (No Touching) ---
            # Scan for existing tents and enforce the "no touching" rule aggressively
            # This acts as a powerful pruner
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == TENT:
                        for dr in [-1, 0, 1]:
                            for dc in [-1, 0, 1]:
                                if dr == 0 and dc == 0: continue
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < R and 0 <= nc < C:
                                    if grid[nr][nc] == TENT:
                                        return False # Two tents touching
                                    if grid[nr][nc] == UNKNOWN:
                                        # Mark as grass to prevent future placement
                                        grid[nr][nc] = GRASS
                                        changed = True
        return True

    def solve_backtrack():
        """Recursive backtracking engine guided by constraint propagation."""

        # 1. Apply logic to reduce search space
        if not propagate():
            return None # Contradiction found

        # 2. Check completion status
        row_cur = [sum(1 for c in range(C) if grid[r][c] == TENT) for r in range(R)]
        col_cur = [sum(1 for r in range(R) if grid[r][c] == TENT) for c in range(C)]

        is_complete = (
            all(row_cur[r] == row_targets[r] for r in range(R)) and
            all(col_cur[c] == col_targets[c] for c in range(C))
        )

        if is_complete:
            # Final sanity check: ensure every tree has a tent (should be guaranteed by counts)
            for tr, tc in trees:
                satisfied = any(
                    grid[tr+dr][tc+dc] == TENT 
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] 
                    if 0 <= tr+dr < R and 0 <= tc+dc < C
                )
                if not satisfied:
                    return None
            return get_result_grid()

        # 3. Heuristic Selection: Choose the most constrained unsatisfied tree
        # This mimics human intuition: "Which tree has the fewest options left?"
        best_tree = None
        min_options = 10 

        for tr, tc in trees:
            # Skip if tree already has a tent
            has_tent = any(
                grid[tr+dr][tc+dc] == TENT 
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] 
                if 0 <= tr+dr < R and 0 <= tc+dc < C
            )
            if has_tent:
                continue

            # Count valid unknown neighbors
            options = [
                (tr+dr, tc+dc) 
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] 
                if 0 <= tr+dr < R and 0 <= tc+dc < C and grid[tr+dr][tc+dc] == UNKNOWN
            ]

            if 0 < len(options) < min_options:
                min_options = len(options)
                best_tree = (tr, tc, options)

        # Fallback if no tree options found (shouldn't happen in valid partial state)
        if not best_tree:
            return None

        # 4. Branching: Try each valid option for the selected tree
        tr, tc, options = best_tree
        for nr, nc in options:
            # Create a snapshot of the current state for backtracking
            grid_snapshot = [row[:] for row in grid]

            # Hypothesis: Place tent here
            grid[nr][nc] = TENT

            result = solve_backtrack()
            if result is not None:
                return result # Found solution

            # Backtrack: Restore state
            for r in range(R):
                for c in range(C):
                    grid[r][c] = grid_snapshot[r][c]

            # Implicitly, this branch failed. 
            # Note: We do NOT permanently mark (nr, nc) as GRASS here globally, 
            # because another tree might theoretically force it later in a different context,
            # though logically if this tree needed it and it failed, it's likely grass.
            # However, strict DFS requires us to just restore and try next option.

        return None # All options exhausted

    # Execute solver
    solution = solve_backtrack()
    return solution if solution else "No Solution"

