            for tr, tc in trees:
                satisfied = any(
                    grid[tr+dr][tc+dc] == TENT 
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] 
                    if 0 <= tr+dr < R and 0 <= tc+dc < C
                )
