OBSERVATION = {'data': [[None, None, None, None, None, 'W'], [None, None, 'B', 'W', None, None], [None, None, None, 'W', 'B', None], [None, None, 'W', None, 'W', None], [None, None, None, 'B', None, None], [None, None, 'B', None, None, None]]}

def solve(observation):
    """
    Solves the Yin-Yang (Black-White) puzzle with connectivity and 2x2 constraints.
    Uses backtracking with constraint propagation and connectivity pruning.
    """
    initial_data = observation['data']
    n = len(initial_data)

    # Deep copy to mutable board
    board = [row[:] for row in initial_data]

    # Directions: up, down, left, right
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        """Return valid orthogonal neighbors."""
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                yield (nr, nc)

    def check_local_2x2(r, c, color):
        """
        Check if placing 'color' at (r,c) creates any 2x2 monochromatic square.
        Only checks the up to 4 squares that include (r,c).
        """
        # Check all 2x2 windows where (r,c) is the bottom-right, bottom-left, top-right, or top-left
        for dr in [-1, 0]:
            for dc in [-1, 0]:
                r0, c0 = r + dr, c + dc
                if 0 <= r0 < n - 1 and 0 <= c0 < n - 1:
                    # Get the four cells of this 2x2 window
                    cells = [
                        board[r0][c0],
                        board[r0][c0 + 1],
                        board[r0 + 1][c0],
                        board[r0 + 1][c0 + 1]
                    ]
                    # Replace the position (r,c) with the proposed color if it was None
                    # (since we haven't committed it to board yet in validation phase, 
                    # but here we assume board[r][c] is already set for checking)
                    if all(v is not None for v in cells):
                        if cells[0] == cells[1] == cells[2] == cells[3]:
                            return False
        return True

    def check_color_connectivity(color):
        """
        Checks if all cells of 'color' can still potentially form a single connected region.
        A cell is reachable if we can traverse through:
        - Cells of the same 'color'
        - Unassigned cells (None) - treating them as potential connectors
        We must NOT traverse through cells of the opposite color.

        Returns False if any 'color' cell is isolated from others by opposite color walls.
        """
        color_cells = []
        for i in range(n):
            for j in range(n):
                if board[i][j] == color:
                    color_cells.append((i, j))

        if len(color_cells) <= 1:
            return True

        # BFS from first color cell
        start = color_cells[0]
        visited = {start}
        queue = [start]

        while queue:
            cr, cc = queue.pop(0)
            for nr, nc in get_neighbors(cr, cc):
                if (nr, nc) not in visited:
                    cell_val = board[nr][nc]
                    # Can pass through own color or unassigned (potential path)
                    if cell_val == color or cell_val is None:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        # If any color cell wasn't reachable, it's cut off by opposite color
        return all(cell in visited for cell in color_cells)

    def validate_placement(r, c, color):
        """Check if placing color at (r,c) is valid according to all constraints."""
        # Temporarily place
        original = board[r][c]
        board[r][c] = color

        valid = True

        # 1. Check 2x2 constraint (local)
        if not check_local_2x2(r, c, color):
            valid = False
        else:
            # 2. Check connectivity potential for both colors
            # If we placed Black, check if White is still connectable (and vice versa)
            # Also check if the placed color itself is internally connectable
            opp = 'W' if color == 'B' else 'B'
            if not check_color_connectivity(color):
                valid = False
            elif not check_color_connectivity(opp):
                valid = False

        # Undo temporary placement
        board[r][c] = original
        return valid

    def find_best_cell():
        """
        Find the next empty cell using MRV (Minimum Remaining Values) heuristic.
        Prefers cells with more assigned neighbors (more constrained).
        """
        best_cell = None
        min_options = 3  # Max options is 2 (B or W)
        max_neighbors = -1

        for i in range(n):
            for j in range(n):
                if board[i][j] is None:
                    # Count assigned neighbors
                    neighbor_count = sum(1 for _, _ in get_neighbors(i, j) if board[_][_] is not None)

                    # Count valid options
                    options = 0
                    if validate_placement(i, j, 'B'):
                        options += 1
                    if validate_placement(i, j, 'W'):
                        options += 1

                    if options == 0:
                        return (i, j)  # Dead end, return immediately

                    if options < min_options or (options == min_options and neighbor_count > max_neighbors):
                        min_options = options
                        max_neighbors = neighbor_count
                        best_cell = (i, j)

        return best_cell

    def check_final_solution():
        """Verify complete solution meets all criteria strictly."""
        # Check 2x2 (should already be satisfied, but double-check)
        for i in range(n - 1):
            for j in range(n - 1):
                vals = [board[i][j], board[i][j+1], board[i+1][j], board[i+1][j+1]]
                if vals[0] == vals[1] == vals[2] == vals[3]:
                    return False

        # Check strict connectivity for both colors (no unassigned allowed now)
        for color in ['B', 'W']:
            color_cells = [(i, j) for i in range(n) for j in range(n) if board[i][j] == color]
            if not color_cells:
                continue

            visited = {color_cells[0]}
            stack = [color_cells[0]]

            while stack:
                cr, cc = stack.pop()
                for nr, nc in get_neighbors(cr, cc):
                    if (nr, nc) not in visited and board[nr][nc] == color:
                        visited.add((nr, nc))
                        stack.append((nr, nc))

            if len(visited) != len(color_cells):
                return False

        return True

    def backtrack():
        """Recursive backtracking solver with constraint propagation."""
        # Find next cell to fill
        cell = find_best_cell()

        if cell is None:
            # No empty cells found - board is complete
            return check_final_solution()

        r, c = cell

        # Try both colors
        for color in ['B', 'W']:
            if validate_placement(r, c, color):
                board[r][c] = color

                if backtrack():
                    return True

                board[r][c] = None

        return False

    # Execute solver
    if backtrack():
        return board
    else:
        return "No Solution"

