    def check_2x2_local(grid, r, c, val):
        """Check if setting (r,c)=val creates any 2x2 monochrome block"""
        for dr in [-1, 0]:
            for dc in [-1, 0]:
                r0, c0 = r + dr, c + dc
                if 0 <= r0 < n-1 and 0 <= c0 < n-1:
