        return True

    def get_component(grid, sr, sc, color):
        """BFS to find connected component of specific color"""
        visited = set()
        stack = [(sr, sc)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited or grid[r][c] != color:
